"""Phase 1 MOCK extraction (step 1b). Generated by code from templates, NOT by an AI model.

Produces the same artefacts as the Phase 2 two-pass extraction (SPEC §7 two_pass):
  pass 1  : raw output "with citations" (here: a templated text listing each requirement with its cited passage)
  pass 2  : JSON in the ExtractionOutput schema; code copies the citations across
followed by the real code steps: schema validation, citation check and highlighting on the placeholder PDF.
"""
from __future__ import annotations

from pathlib import Path

from .. import citations, schemas
from .requirements import ANOMALIES, LOTS

MOCK_MODEL = "none (mock generated by code)"


def prompt_input(rec: dict, retrieval: dict, chunks: list[dict]) -> dict:
    """Exactly what the extraction prompt receives: notice fields needed for the task (no contact fields) +
    retrieved passages."""
    o = rec["original"]
    fields = ["doffin_id", "title", "title_en", "description", "notice_type", "contract_type", "procedure",
              "tender_deadline_utc", "lot_count", "estimated_value", "currency", "cpv_main", "cpv_additional",
              "framework_agreement", "dynamic_purchasing_system", "place_of_performance_nuts", "legislation"]
    sel = set(retrieval["retrieved_page_ids"])
    return {"notice": {k: o.get(k, "") for k in fields},
            "notice_version_hash": rec["version_hash"],
            "passages": [{"page_id": c["page_id"], "document": c["document"], "page": c["page"], "text": c["text"]}
                         for c in chunks if c["page_id"] in sel]}


def run(rec: dict, reqs_tpl: list[dict], layout: dict, pdf_path: Path, prompt_version: str) -> dict:
    nid = rec["doffin_id"]
    anomaly = ANOMALIES.get(nid, {})
    doc = pdf_path.name
    reqs = []
    raw_lines = [f"[MOCK pass 1 — generated by code, no model call] Notice {nid}"]
    for t in reqs_tpl:
        page = layout.get(t["key"])
        uncited = t["key"] in anomaly.get("uncited", [])
        src = None if uncited or not page else {"document": doc, "page_start": page, "page_end": page,
                                                 "cited_text": t["sentence_nb"]}
        conf = "low" if uncited else ("medium" if t["category"] in ("technical",) else "high")
        reqs.append({"req_id": t["req_id"], "lot_id": t["lot_id"], "category": t["category"],
                     "text_summary_en": t["text_summary_en"], "text_summary_nb": t["text_summary_nb"],
                     "mandatory": t["mandatory"], "proof_demanded": t["proof_demanded"], "proof_type": t["proof_type"],
                     "source": src, "extraction_confidence": conf, "mock": True})
        raw_lines.append(f"- {t['req_id']} ({t['category']}{', lot ' + t['lot_id'] if t['lot_id'] else ''}): "
                         f"{t['text_summary_nb']}"
                         + (f'  <cite doc="{doc}" page="{page}">{t["sentence_nb"]}</cite>' if src else "  [no citation]"))
    conflicts = []
    if "conflict" in anomaly:
        c = anomaly["conflict"]
        conflicts.append({"description_en": c["description_en"], "description_nb": c["description_nb"],
                          "documents": [doc]})
    pass2 = {"notice_id": nid, "notice_version_hash": rec["version_hash"], "prompt_version": prompt_version,
             "model": MOCK_MODEL, "lots": LOTS.get(nid, []), "requirements": reqs,
             "model_self_rating": anomaly.get("model_self_rating", "high"), "conflicts": conflicts, "mock": True}
    ok, validated, errs = schemas.validate(schemas.ExtractionOutput, pass2)
    checks = []
    if ok:
        for r in validated["requirements"]:
            if not r["source"]:
                checks.append({"req_id": r["req_id"], "citation_ok": False, "highlighted": False,
                               "highlight": None, "error": "no citation returned"})
                continue
            res = citations.check_and_highlight(pdf_path, r["source"]["page_start"], r["source"]["cited_text"])
            checks.append({"req_id": r["req_id"], **res})
            if not res["citation_ok"]:
                r["source"] = None              # failed check -> uncited, lowers confidence
                r["extraction_confidence"] = "low"
    return {"notice_id": nid, "mock": True, "prompt_version": prompt_version, "model": MOCK_MODEL,
            "raw_output_pass1": "\n".join(raw_lines), "raw_output_pass2": pass2,
            "schema_ok": ok, "schema_errors": errs, "validated": validated, "citation_checks": checks,
            "anomaly_note_en": anomaly.get("note_en"), "anomaly_note_nb": anomaly.get("note_nb")}
